#[inline]
pub unsafe fn xmlCharStrndup(
    mut cur: *const c_char,
    mut len: c_int,
) -> *mut xmlChar {
    if cur.is_null() || len < 0 as c_int {
        return ::core::ptr::null_mut::<xmlChar>();
    }

    let ret = xmlMallocAtomic.expect("non-null function pointer")(
        (len as size_t).wrapping_add(1 as size_t),
    ) as *mut xmlChar;
    if ret.is_null() {
        return ::core::ptr::null_mut::<xmlChar>();
    }

    let len_usize = len as usize;
    let src = cur as *const u8;
    let dst = ret;

    let mut i = 0usize;
    while i < len_usize {
        let b = unsafe { *src.add(i) }; // SAFETY: `cur` is assumed valid for reads as required by the original function; `i < len_usize == len as usize`.
        unsafe { *dst.add(i) = b }; // SAFETY: `ret` points to an allocation of `len + 1` bytes, so writing at `i < len` is in-bounds.
        if b == 0 {
            return ret;
        }
        i += 1;
    }

    unsafe { *dst.add(len_usize) = 0 as xmlChar }; // SAFETY: `ret` points to an allocation of `len + 1` bytes, so index `len` is in-bounds.
    ret
}

